// Maintenance only: vendor the pinned MIT implementation; never used at runtime.
import { build } from 'esbuild';
import { createHash } from 'node:crypto';
import { readFile, writeFile, mkdir, copyFile, realpath } from 'node:fs/promises';
import { resolve, dirname, relative, join } from 'node:path';
import { fileURLToPath } from 'node:url';

if (!process.argv[2]) throw new Error('Usage: node src/rea-native/vendor/build.mjs <rea-agents package root>');
const root = await realpath(resolve(process.argv[2]));
const pkg = JSON.parse(await readFile(join(root, 'package.json'), 'utf8'));
if (pkg.name !== 'rea-agents' || pkg.version !== '6.5.0') throw new Error('Expected rea-agents@6.5.0');
const out = dirname(fileURLToPath(import.meta.url));
const imports = [
  ['GoBinaryService', 'application/go/GoBinaryService'],
  ['GoBinaryProvider', 'go/GoBinaryProvider'],
  ['RustBinaryService', 'application/rust/RustBinaryService'],
  ['RustBinaryProvider', 'rust/RustBinaryProvider'],
  ['PeResourcesService', 'application/binaryDiagnostics/PeResourcesService'],
  ['PeResourcesProvider', 'native/pe/PeResourcesProvider'],
  ['ElectronFuseService', 'application/electron/ElectronFuseService'],
  ['ElectronFuseProvider', 'electron/ElectronFuseProvider'],
];
const source = imports.map(([name, path]) => `import { ${name} } from './dist/${path}.js';`).join('\n') + `
import { z } from 'zod';
import { inspectGoBinaryInputSchema } from './dist/domain/go/goBinary.js';
import { inspectRustBinaryInputSchema } from './dist/domain/rust/rustBinary.js';
import { inspectPeResourcesInputSchema } from './dist/domain/native/peResources.js';
import { inspectElectronFusesInputSchema } from './dist/domain/electron/electronFuses.js';
export const inputSchemas = {
  inspect_go_binary: z.toJSONSchema(inspectGoBinaryInputSchema, { io: 'input' }),
  inspect_rust_binary: z.toJSONSchema(inspectRustBinaryInputSchema, { io: 'input' }),
  inspect_pe_resources: z.toJSONSchema(inspectPeResourcesInputSchema, { io: 'input' }),
  inspect_electron_fuses: z.toJSONSchema(inspectElectronFusesInputSchema, { io: 'input' }),
};
export const createServices = () => ({
  inspect_go_binary: new GoBinaryService(new GoBinaryProvider()),
  inspect_rust_binary: new RustBinaryService(new RustBinaryProvider()),
  inspect_pe_resources: new PeResourcesService(new PeResourcesProvider()),
  inspect_electron_fuses: new ElectronFuseService(new ElectronFuseProvider()),
});
`;
const result = await build({ absWorkingDir: root, stdin: { contents: source, resolveDir: root, sourcefile: 'dsh-offline-entry.mjs' },
  bundle: true, platform: 'node', format: 'esm', target: 'node22', write: false, metafile: true,
  legalComments: 'inline', banner: { js: '// REA 6.5.0 MIT source port. Generated by build.mjs; see provenance.json and LICENSE.' },
});
const sources = [];
const packages = new Set();
for (const path of Object.keys(result.metafile.inputs)) {
  if (path.replaceAll('\\', '/').endsWith('/dsh-offline-entry.mjs') || path === 'dsh-offline-entry.mjs') continue;
  const absolute = resolve(root, path);
  const rel = relative(root, absolute).replaceAll('\\', '/');
  const bytes = await readFile(absolute);
  sources.push({ path: rel, sha256: createHash('sha256').update(bytes).digest('hex'), bytes: bytes.length });
  const match = rel.match(/(?:^|\/)node_modules\/((?:@[^/]+\/)?[^/]+)/);
  if (match) packages.add(match[1]);
}
await writeFile(join(out, 'runtime.mjs'), result.outputFiles[0].contents);
await copyFile(join(root, 'LICENSE'), join(out, 'LICENSE'));
const licenses = [];
await mkdir(join(out, 'licenses'), { recursive: true });
for (const name of packages) {
  const directory = join(root, 'node_modules', name);
  const metadata = JSON.parse(await readFile(join(directory, 'package.json'), 'utf8'));
  const { readdir } = await import('node:fs/promises');
  const names = (await readdir(directory)).filter(item => /^(license|copying)(\.|$)/i.test(item));
  if (names.length === 0) throw new Error(`No license file for ${name}`);
  for (const license of names) await copyFile(join(directory, license), join(out, 'licenses', `${name.replaceAll('/', '__')}__${license}`));
  licenses.push({ name, version: metadata.version, license: metadata.license });
}
await writeFile(join(out, 'provenance.json'), JSON.stringify({ package: pkg.name, version: pkg.version,
  license: pkg.license, entry: source, dependencies: licenses, sources,
  outputSha256: createHash('sha256').update(result.outputFiles[0].contents).digest('hex'),
}, null, 2) + '\n');
console.log(JSON.stringify({ sourceFiles: sources.length, dependencies: licenses, bytes: result.outputFiles[0].contents.length }));
